display.text:
import sharp from 'sharp';

import { aiImageConfig } from '@/lib/config/ai-images';
import { logger } from '@/lib/observability/logger';

export type DiagramRequest = {
  title?: string;
  description: string;
  labels?: string[];
  subjectContext?: string;
  aspectRatio?: '4:3' | '1:1';
};

type GenerateDiagramResult = {
  buffer: Buffer;
  mimeType: string;
  modelUsed: string;
  prompt: string;
  fallbackUsed: boolean;
  sizeBytes: number;
};

interface AIClient {
  generateImage(input: { prompt: string; model?: string }): Promise<Buffer>;
}

function buildPrompt(request: DiagramRequest) {
  const parts = [
    'Create a clean, school-safe science diagram with crisp, legible labels.',
    'Use clear vector-style shapes, light background, and no watermarks or branding.',
    'Include accurate text labels directly on the diagram; avoid excessive decorative text.',
    'Ensure text is readable at 4:3 or square aspect ratios; no NSFW or disallowed content.',
  ];

  if (request.title) {
    parts.push(`Diagram focus: ${request.title}`);
  }

  if (request.subjectContext) {
    parts.push(`Context: ${request.subjectContext}`);
  }

  parts.push(`Diagram goal: ${request.description}`);

  if (request.labels?.length) {
    parts.push(`Required labels: ${request.labels.join(', ')}`);
  }

  if (request.aspectRatio) {
    parts.push(`Preferred aspect ratio: ${request.aspectRatio}`);
  } else {
    parts.push('Preferred aspect ratio: 4:3 or 1:1 (whichever best fits).');
  }

  return parts.join('\n');
}

async function optimizeImage(buffer: Buffer) {
  const qualityLevels = [80, 70, 60, 50, 40];
  let lastBuffer = buffer;

  for (const quality of qualityLevels) {
    const optimized = await sharp(buffer)
      .resize({ width: aiImageConfig.maxWidth, withoutEnlargement: true })
      .webp({ quality })
      .toBuffer();

    lastBuffer = optimized;

    if (optimized.byteLength <= aiImageConfig.maxBytes) {
      return {
        buffer: optimized,
        mimeType: 'image/webp',
        sizeBytes: optimized.byteLength,
      };
    }
  }

  return {
    buffer: lastBuffer,
    mimeType: 'image/webp',
    sizeBytes: lastBuffer.byteLength,
  };
}

export class ImageGenerator {
  constructor(private readonly client: AIClient) {}

  async generateDiagram(request: DiagramRequest): Promise<GenerateDiagramResult> {
    const prompt = buildPrompt(request);
    const modelsToTry = [
      aiImageConfig.primaryModel,
      ...aiImageConfig.fallbackModels,
    ].filter((value, index, array) => Boolean(value) && array.indexOf(value) === index);

    let lastError: Error | null = null;

    for (const modelId of modelsToTry) {
      try {
        const rawBuffer = await this.client.generateImage({ prompt, model: modelId });
        const optimized = await optimizeImage(rawBuffer);

        if (optimized.sizeBytes > aiImageConfig.maxBytes) {
          logger.warn('ai.image.optimization_limit_exceeded', {
            model: modelId,
            sizeBytes: optimized.sizeBytes,
            maxBytes: aiImageConfig.maxBytes,
          });
        }

        return {
          buffer: optimized.buffer,
          mimeType: optimized.mimeType,
          modelUsed: modelId,
          prompt,
          fallbackUsed: modelId !== aiImageConfig.primaryModel,
          sizeBytes: optimized.sizeBytes,
        };
      } catch (error) {
        lastError = error instanceof Error ? error : new Error('Unknown error');
        logger.warn('ai.image.model_error', {
          model: modelId,
          error: lastError.message,
        });
      }
    }

    throw lastError ?? new Error('Image generation failed for all models');
  }
}

function ensureApiKey(modelId: string) {
  if (modelId.startsWith('google/') && !aiImageConfig.googleApiKey) {
    throw new Error('Missing GOOGLE_API_KEY or GEMINI_API_KEY for Google image generation');
  }
  if (modelId.startsWith('openai/') && !aiImageConfig.openaiApiKey) {
    throw new Error('Missing OPENAI_API_KEY for OpenAI image generation');
  }
}

export async function generateLessonDiagram(
  request: DiagramRequest
): Promise<GenerateDiagramResult> {
  const { experimental_generateImage } = await import('ai');

  const client: AIClient = {
    async generateImage(input) {
      ensureApiKey(input.model ?? aiImageConfig.primaryModel);
      const { image } = await experimental_generateImage({
        model: input.model ?? aiImageConfig.primaryModel,
        prompt: input.prompt,
      });
      if (!image) {
        throw new Error(`Model ${input.model} did not return an image`);
      }
      return Buffer.from(image.base64, 'base64');
    },
  };

  const service = new ImageGenerator(client);
  return service.generateDiagram(request);
}

/**
 * Phase 7 Red-phase tests: refactor `lib/ai/image-generator.ts`
 * to depend on the shared `@reading-advantage/ai` `AIClient` interface.
 *
 * See `measure/tracks/ai_adapter_package_20260603/plan.md` Phase 7:
 *   - Task 1: Write a failing test for the new `ImageGenerator` class
 *     (constructor takes `AIClient`; `generateDiagram(input)` calls
 *     `client.generateImage(...)`).
 *   - Task 2: Remove the `process.env.OPENAI_API_KEY` /
 *     `process.env.GOOGLE_API_KEY` mutation in `ensureApiKey()`.
 *
 * RED expectations on first run (pre-implementation):
 *   - `ImageGenerator` is not yet exported from `./image-generator`.
 *     Every test in this file except the legacy-wrapper-preservation
 *     test fails with the `Phase 7 RED:` `TypeError` thrown by
 *     `resolveImageGenerator`.
 *   - The legacy `generateLessonDiagram(input)` wrapper is still
 *     exported and must continue to be exported by Green, because
 *     Phase 7 task 3 ("Refactor the existing `generateLessonDiagram(input)`
 *     exported function into a thin wrapper") requires the public
 *     surface to be preserved for the existing call site at
 *     `components/features/lesson/blocks/image-block.tsx`.
 *
 * GREEN expectations after the implementer lands the refactor:
 *   - The new `ImageGenerator` class is exported and accepts an
 *     `AIClient` in its constructor.
 *   - `service.generateDiagram(request)` delegates to
 *     `client.generateImage(...)` with the built prompt and the
 *     primary model from `aiImageConfig`, and returns a `Buffer` in
 *     the legacy `GenerateDiagramResult` shape.
 *   - `service.generateDiagram(request)` does NOT mutate
 *     `process.env.OPENAI_API_KEY` or `process.env.GOOGLE_API_KEY`
 *     at call time (test-strategy §3.2 / FR-5).
 *   - Falls back to the secondary model on primary failure.
 *   - The legacy `generateLessonDiagram(input)` wrapper is preserved.
 */
